def solve_mask(grid, mask, color):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    mh=max(r for r,c in mask)+1; mw=max(c for r,c in mask)+1
    for dr in range(h-mh+1):
        for dc in range(w-mw+1):
            if all(grid[dr+r][dc+c]==0 for r,c in mask):
                for r,c in mask: out[dr+r][dc+c]=color
    return out
